// Accept a raw webhook POST (payload under .body) or a direct/sub-workflow call.
const raw = $input.first().json;
const src = raw.body || raw;

const vehicleValue = parseFloat(src.vehicleValue);
const loanPayoffAmount = parseFloat(src.loanPayoffAmount);
// Credit score is entered manually by the rep from the customer's AECB report --
// real-time bureau lookups require a licensed financial-institution agreement in
// the UAE, so this stays a manual field rather than an automated external call.
const creditScore = parseInt(src.creditScore, 10);

const errors = [];
if (!Number.isFinite(vehicleValue) || vehicleValue <= 0) {
  errors.push('vehicleValue must be a positive number (AED).');
}
if (!Number.isFinite(loanPayoffAmount) || loanPayoffAmount < 0) {
  errors.push('loanPayoffAmount must be zero or a positive number (AED).');
}
if (!Number.isFinite(creditScore) || creditScore < 300 || creditScore > 900) {
  errors.push('A valid AECB credit score (300-900) is required. Ask the customer for their latest AECB report.');
}

if (errors.length) {
  return [{ json: { status: 'error', errors: errors, calculatedAt: new Date().toISOString() } }];
}

const equity = vehicleValue - loanPayoffAmount;
const ltv = vehicleValue > 0 ? Math.round((loanPayoffAmount / vehicleValue) * 1000) / 10 : null;

let financeTier = 'Subprime';
let indicativeApr = 12.5;
if (creditScore >= 720)      { financeTier = 'Prime Plus'; indicativeApr = 3.99; }
else if (creditScore >= 680) { financeTier = 'Prime';      indicativeApr = 5.49; }
else if (creditScore >= 620) { financeTier = 'Near Prime'; indicativeApr = 7.99; }

return [{
  json: {
    status: 'success',
    equity_aed: Math.round(equity),
    equity_status: equity >= 0 ? 'Positive' : 'Negative',
    loan_to_value_pct: ltv,
    credit_score: creditScore,
    finance_tier: financeTier,
    indicative_apr_pct: indicativeApr,
    vehicle_value_aed: Math.round(vehicleValue),
    loan_payoff_aed: Math.round(loanPayoffAmount),
    disclaimer: 'Indicative only. Final APR and approval are set by the lender, not by NEXUS OS.',
    calculated_at: new Date().toISOString()
  }
}];
